def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    instance_obj_mad = feature_cache['instance_obj_mad']
    eps = 1e-6
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    if b_idx.numel() == 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_linear_instance_mad_fixed', 'weight_family': 'gap_linear'})
    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp_min(0.0)
    weight = gap / instance_obj_mad[b_idx].clamp_min(eps)
    weight = weight.clamp(min=0.1, max=5.0)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_linear_instance_mad_fixed', 'weight_family': 'gap_linear'})
